/**
 * WO#252-B — FP-guard precedence phrases (Arabic, pre-normalised).
 *
 * A crisis trigger that is a *substring* of a valid Qur'anic / devotional
 * phrase (trigger ⊂ guard) must not fire when the user typed the longer
 * phrase. detectCrisis strips these guard phrases from the normalised input
 * before keyword matching, so the trigger inside the guard disappears while
 * any independent trigger elsewhere in the text still fires.
 *
 * Only "ya laytani muttu" / "...qabla hadha" (Qur'an 19:23, Maryam) needs
 * this today — the FP-guard set (§2) is safe by omission (no trigger is a
 * substring of any of them; asserted in crisis-mechanics.test.ts).
 */
export const SELF_HARM_GUARDS: ReadonlyArray<string> = [
  "يا ليتني مت قبل هذا",
]

import { normaliseArabic, containsArabic } from './arabic-normalise.js'
import { foldLatin } from './latin-fold.js'
import {
  normaliseSeparators, collapseLetterSpacing, englishVariants, matchesSquashed, isSquashable, boundedIncludes,
} from './crisis-normalise.js'

/**
 * WO#308 — apostrophe normalisation. Contraction keywords ("don't want to be
 * alive", "can't go on", "i'm a burden", "wish i wasn't here") silently missed
 * the extremely common apostrophe-free mobile spelling ("dont", "cant", "im",
 * "wasnt"). Stripping every apostrophe variant (straight ' , curly ’ , grave ` ,
 * acute ´ , modifier ʼ) from BOTH the folded input and the folded keyword makes
 * the already-reviewed phrases fire on either spelling. FP-neutral: it only
 * removes a character, it never adds a new match surface. Applied in both
 * matchesAny and matchesAnyExcept, so it covers SELF_HARM_KEYWORDS and
 * ABUSE_KEYWORDS alike.
 */
function stripApostrophes(s: string): string {
  return s.replace(/['’`´ʼ]/g, '')
}

/**
 * WO#391 (Gem 3, 27 Sep 2026): the prepared input. Every form is for MATCHING
 * ONLY; the caller's text is never altered. See crisis-normalise.ts.
 *   - `latin`     lower-cased, Latin-folded, apostrophes stripped, then steps
 *                 1, 2 and 6 (zero-width, separators, Unicode dashes/spaces);
 *                 plus the step 4 letter-spacing collapse as a second base.
 *   - `english`   steps 3 and 5 (leetspeak, repeated letters) on each base,
 *                 matched against ENGLISH keywords only.
 *   - `arabic`    steps 1 and 2, then normaliseArabic (WO#97 / WO#252-A).
 *                 Arabic script gets nothing else (Gem 2 open item).
 */
interface PreparedInput {
  latin: string[]
  english: string[]
  arabic: string
}

function prepareInput(text: string): PreparedInput {
  const folded = normaliseSeparators(stripApostrophes(foldLatin(text.toLowerCase())))
  const latin = [...new Set([folded, collapseLetterSpacing(folded)])]
  const english = [...new Set(latin.flatMap(englishVariants))].filter((v) => !latin.includes(v))
  let arabic = normaliseArabic(normaliseSeparators(text))
  // WO#252-B — FP-guard precedence: strip guard phrases so a trigger that is a
  // substring of a valid Qur'anic/devotional phrase does not fire when the user
  // typed the longer phrase. Independent triggers elsewhere are untouched.
  for (const guard of SELF_HARM_GUARDS) {
    if (guard) arabic = arabic.split(guard).join('')
  }
  return { latin, english, arabic }
}

/** A keyword in the form it is matched in, computed once per keyword. */
interface PreparedKeyword {
  arabic: boolean
  norm: string
  english: boolean
  squash: boolean
  /** true for every English keyword except the end-bounded ones above. */
  openEnd: boolean
}

/**
 * WO#391 addendum (d), Architect correction on 2e02e5f: every English keyword
 * matches from a word START boundary ("skill myself", "draped" no longer hit),
 * but only these keywords also need an END boundary, because only they have a
 * known false-positive continuation: "self harm" (self-harmony) and the
 * "hits me" family (the hits media). Every other English keyword stays
 * open-ended at the end, as before WO#391, so glued tails such as
 * "kill myselfnow" and stems such as "suicid" (suicidal) still hit.
 * A lost hit on a self-harm phrase is a safety regression and outranks a
 * false positive; widen this set only on a Gem 3 ruling.
 */
function needsEndBoundary(norm: string): boolean {
  return norm === 'self harm' || norm.endsWith(' hits me')
}

/**
 * WO#500, the Architect's rulings (24 Oct 2026, pending Gem 3): EVERY English
 * ABUSE keyword ends at a word boundary (an inflection -ing/-ed/-s/-er and a
 * repeated final letter still allowed, boundedIncludes). Open at the end,
 * "abusing me" matched "abusing medication", "violent to me" "violent to men",
 * "beating me" "beating meat" and "they hit me" "they hit metal". Self-harm
 * keywords keep the open end (a lost self-harm hit outranks a false positive).
 */
const ABUSE_EN_END_BOUNDED: ReadonlySet<string> = new Set(ABUSE_KEYWORDS_EN)

/**
 * WO#391, Gem 3 ruling (27 Sep 2026, Option 2): "kms" ("kill myself") is not
 * a hit when the word right after it is a distance word, so "5 kms walk" and
 * "10 kms away" do not fire. Only that occurrence is skipped: "kms" anywhere
 * else, including after a number ("day 3 kms"), still hits. Residual false
 * positive accepted by Gem 3: "ran 5 kms today".
 */
const KEYWORD_SUPPRESS_AFTER: Readonly<Record<string, RegExp>> = {
  kms: /^ (?:walk|away|run|drive|from)(?![\p{L}\p{N}])/u,
}

const ENGLISH_KEYWORDS: ReadonlySet<string> = new Set([...SELF_HARM_KEYWORDS_EN, ...ABUSE_KEYWORDS_EN])
const preparedCache = new Map<string, PreparedKeyword>()

function prepareKeyword(k: string): PreparedKeyword {
  let p = preparedCache.get(k)
  if (!p) {
    const arabic = containsArabic(k)
    // The keyword goes through the same pipeline as the input, so a stored
    // "self-harm" and a typed "self harm" meet as "self harm".
    const norm = arabic
      ? normaliseArabic(normaliseSeparators(k))
      : normaliseSeparators(stripApostrophes(foldLatin(k.toLowerCase())))
    const english = !arabic && ENGLISH_KEYWORDS.has(k)
    p = { arabic, norm, english, squash: !arabic && isSquashable(norm), openEnd: !needsEndBoundary(norm) && !ABUSE_EN_END_BOUNDED.has(k) }
    preparedCache.set(k, p)
  }
  return p
}

/**
 * One keyword against the prepared input. Arabic-script keywords match the
 * Arabic form only. Latin keywords match either base as a substring (the
 * pre-WO#391 rule; English keywords from a word start boundary, and end-
 * bounded only where needsEndBoundary says, addendum (d)),
 * English ones also match the leet / repeat variants, and
 * a Latin keyword of 6+ letters also matches in no-separator form on token
 * boundaries (step 7).
 */
function keywordHits(k: string, input: PreparedInput): boolean {
  const p = prepareKeyword(k)
  if (!p.norm) return false
  if (p.arabic) return input.arabic.includes(p.norm)
  const forms = p.english ? [...input.latin, ...input.english] : input.latin
  for (const f of forms) {
    // English keywords match from a word start boundary, and the few listed
    // in needsEndBoundary also end at one (addendum (d)); every other
    // Latin-script language keeps substring matching (Turkish, Indonesian
    // and roman Urdu attach suffixes a boundary rule would cut off).
    if (p.english ? boundedIncludes(f, p.norm, p.openEnd, KEYWORD_SUPPRESS_AFTER[p.norm]) : f.includes(p.norm)) return true
    if (p.squash && matchesSquashed(f, p.norm)) return true
  }
  return false
}

/**
 * Apply detection over a keyword list. Both the keyword and the input are
 * folded the same way (WO#97 §S3D, WO#252-A, WO#308 apostrophes, WO#391
 * separators and variants), so normalisation can only ADD matches.
 */
function matchesAny(keywords: ReadonlyArray<string>, input: PreparedInput): boolean {
  for (const k of keywords) if (keywordHits(k, input)) return true
  return false
}

/**
 * Detect crisis keywords in user input.
 * Self-harm is checked first (higher acuity).
 *
 * The input is prepared once (prepareInput above) and shared across both
 * keyword-list checks: the Latin forms for English / transliterated /
 * Indonesian / Turkish / Bengali keywords (acronyms like `'kdrt'` rely on the
 * lower-casing), and the Arabic form (WO#97 §S3D) so chat-typed Arabic without
 * hamza / tashkeel matches the formal-MSA spellings. WO#391 adds separator,
 * zero-width, leetspeak, letter-spacing, repeated-letter and no-separator
 * normalisation; see crisis-normalise.ts.
 */
/**
 * WO#265 — bare-noun frame-suppression (Gem 2 four-gate, Architect-tightened).
 *
 * These 6 crisis keywords are common informational / fiqh lookups when bare
 * ("is X haram", "definition of X"), so a LONE hit on one of them is gated: it
 * FIRES unless an informational-frame marker is present, NO disclosure marker is
 * present, and the input is <= 8 words. Any co-occurring crisis trigger (gate 1),
 * any disclosure marker (gate 3), or > 8 words (gate 4) => FIRE. Suppression is
 * the catastrophic direction, so every ambiguous branch defaults to FIRE. Applies
 * to THESE 6 ONLY — every other crisis keyword fires exactly as before. Markers
 * run through the SAME normalisation pipeline (WO#263 ZWNJ/NFC/fold) via matchesAny.
 */
export const BARE_NOUN_GUARDS: ReadonlyArray<{ kw: string; type: 'self-harm' | 'abuse'; locale: 'fa' | 'bn' }> = [
  { kw: "خودکشی", type: 'self-harm', locale: 'fa' },
  { kw: "خشونت خانگی", type: 'abuse', locale: 'fa' },
  { kw: "ازار جنسی", type: 'abuse', locale: 'fa' },
  { kw: "আত্মহত্যা", type: 'self-harm', locale: 'bn' },
  { kw: "পারিবারিক সহিংসতা", type: 'abuse', locale: 'bn' },
  { kw: "যৌন নির্যাতন", type: 'abuse', locale: 'bn' },
]
const BARE_NOUN_SET = new Set<string>(BARE_NOUN_GUARDS.map((g) => g.kw))

// Gem 2 marker sets (exported so the QA matrix builds cases from the real data).
export const FA_FRAME_MARKERS: ReadonlyArray<string> = ["حکم", "گناه", "مجازات", "تعریف", "چیست", "ایا", "حرام", "حلال", "جایز", "اسلام", "دین", "شرع", "قران", "قانون", "کفاره", "عذاب", "دیه", "شرایط", "گناهش"]
export const FA_DISCLOSURE_MARKERS: ReadonlyArray<string> = ["من", "میخواهم", "میخوام", "خسته", "شدم", "کردم", "کمک", "نجات", "شوهرم", "پدرم", "خانوادم", "برادرم", "زنم", "دیگه", "نمیتونم", "نمیخوام", "خودم", "بمیرم", "کشتن", "بکشم", "کتک", "زد", "درد", "میترسم", "تهدید", "خون"]
export const BN_FRAME_MARKERS: ReadonlyArray<string> = ["কি", "কী", "পাপ", "শাস্তি", "আইন", "ইসলামে", "ইসলামী", "হারাম", "জায়েজ", "জায়েয", "হুকুম", "বিধান", "কুরআনে", "হাদিসে", "সংজ্ঞা", "কাফফারা", "অপরাধ", "অধিকার"]
export const BN_DISCLOSURE_MARKERS: ReadonlyArray<string> = ["আমি", "আমার", "আমাকে", "চাই", "কষ্ট", "পারছি", "বাঁচতে", "সাহায্য", "স্বামী", "বাবা", "পরিবার", "ভাই", "স্ত্রী", "মরে", "মরতে", "নিজেকে", "আর", "সহ্য", "খুব", "মেরেছে", "মারধর", "ভয়"]
const FRAME_MARKERS: ReadonlyArray<string> = [...FA_FRAME_MARKERS, ...BN_FRAME_MARKERS]
const DISCLOSURE_MARKERS: ReadonlyArray<string> = [...FA_DISCLOSURE_MARKERS, ...BN_DISCLOSURE_MARKERS]

/** matchesAny but skipping any keyword in `exclude` (the bare-noun set). */
function matchesAnyExcept(keywords: ReadonlyArray<string>, exclude: Set<string>, input: PreparedInput): boolean {
  for (const k of keywords) {
    if (exclude.has(k)) continue
    if (keywordHits(k, input)) return true
  }
  return false
}

/** Distinct bare-noun guards that hit the (normalised) input. */
function bareNounHits(input: PreparedInput): Array<{ kw: string; type: CrisisType }> {
  const hits: Array<{ kw: string; type: CrisisType }> = []
  for (const g of BARE_NOUN_GUARDS) {
    if (keywordHits(g.kw, input)) hits.push({ kw: g.kw, type: g.type })
  }
  return hits
}

function wordCount(text: string): number {
  const t = text.trim()
  return t ? t.split(/\s+/).length : 0
}

/**
 * Gates 2-4 for a lone bare-noun hit (gate 1 is handled by the caller).
 * true = FIRE crisis, false = SUPPRESS (informational frame, no disclosure, short).
 */
function fireBareNoun(text: string, input: PreparedInput): boolean {
  if (!matchesAny(FRAME_MARKERS, input)) return true       // gate 2: no frame => FIRE
  if (matchesAny(DISCLOSURE_MARKERS, input)) return true   // gate 3: disclosure => FIRE
  return wordCount(text) > 8                                            // gate 4: <=8 SUPPRESS, >8 FIRE
}

export function detectCrisis(text: string): CrisisDetectionResult {
  // WO#252-A Latin fold + WO#391 normalisation, prepared once and shared
  // across both keyword-list checks. `text` itself is never modified.
  const input = prepareInput(text)

  // WO#265 — non-bare crisis strings fire exactly as before (gate 1: a
  // co-occurring non-bare trigger short-circuits here).
  if (matchesAnyExcept(SELF_HARM_KEYWORDS, BARE_NOUN_SET, input)) {
    return { isCrisis: true, crisisType: 'self-harm' }
  }
  if (matchesAnyExcept(ABUSE_KEYWORDS, BARE_NOUN_SET, input)) {
    return { isCrisis: true, crisisType: 'abuse' }
  }
  // WO#482 (Gem 3 round 2): Turkish relational fear, a relation word then "kork".
  // WO#488 A2: the same rule for Persian and Bengali.
  if (trFearProximity(text, input) || faFearProximity(text, input) || bnFearProximity(text, input)) {
    return { isCrisis: true, crisisType: 'abuse' }
  }
  // Only bare-noun guards can match now — apply the four-gate suppression.
  const hits = bareNounHits(input)
  if (hits.length === 0) return { isCrisis: false, crisisType: 'none' }
  const type: CrisisType = hits.some((h) => h.type === 'self-harm') ? 'self-harm' : 'abuse'
  if (hits.length >= 2) return { isCrisis: true, crisisType: type } // gate 1: 2+ distinct bare nouns
  if (fireBareNoun(text, input)) return { isCrisis: true, crisisType: type }
  return { isCrisis: false, crisisType: 'none' } // suppressed: informational frame
}

/**
 * WO#482: which language lists a crisis input hit. detectCrisis says only
 * whether, and which type; this says in which language, so a caller that
 * has no request locale can answer in the language the person wrote in.
 * It uses the detector's own prepared input and per-keyword matcher, so a
 * list hits here exactly when it would hit inside detectCrisis. It does not
 * decide whether there is a crisis: call it only after detectCrisis fired.
 * Punjabi entries are not split out, so a hit on one of them alone returns
 * []. Persian and Bengali are split out since WO#488.
 */
export type CrisisKeywordLanguage = 'en' | 'id' | 'ur' | 'ar' | 'tr' | 'fa' | 'bn'

const KEYWORDS_BY_LANGUAGE: Readonly<Record<'self-harm' | 'abuse', ReadonlyArray<[CrisisKeywordLanguage, ReadonlyArray<string>]>>> = {
  'self-harm': [
    ['en', SELF_HARM_KEYWORDS_EN],
    ['id', SELF_HARM_KEYWORDS_ID],
    ['ur', SELF_HARM_KEYWORDS_UR],
    ['ar', SELF_HARM_KEYWORDS_AR],
    ['tr', SELF_HARM_KEYWORDS_TR],
    ['fa', SELF_HARM_KEYWORDS_FA],
    ['bn', SELF_HARM_KEYWORDS_BN],
  ],
  abuse: [
    ['en', ABUSE_KEYWORDS_EN],
    ['id', ABUSE_KEYWORDS_ID],
    ['ur', ABUSE_KEYWORDS_UR],
    ['ar', ABUSE_KEYWORDS_AR],
    ['tr', ABUSE_KEYWORDS_TR],
    ['fa', ABUSE_KEYWORDS_FA],
    ['bn', ABUSE_KEYWORDS_BN],
  ],
}

/** The relational-fear rule for a language, if it has one (abuse only). */
const FEAR_PROXIMITY: Partial<Record<CrisisKeywordLanguage, (text: string, input: PreparedInput) => boolean>> = {
  tr: (text, input) => trFearProximity(text, input),
  fa: (text, input) => faFearProximity(text, input),
  bn: (text, input) => bnFearProximity(text, input),
}

export function crisisKeywordLanguages(text: string, crisisType: 'self-harm' | 'abuse'): CrisisKeywordLanguage[] {
  const input = prepareInput(text)
  return KEYWORDS_BY_LANGUAGE[crisisType]
    .filter(([language, keywords]) => matchesAny(keywords, input) || (crisisType === 'abuse' && !!FEAR_PROXIMITY[language]?.(text, input)))
    .map(([language]) => language)
}

/**
 * WO#482, Gem 3 round 2 (21 Oct 2026; docs/wo482-architect.md): Turkish
 * relational fear is ABUSE. A relation word followed by "kork" with up to three
 * words between ("kocamdan korkuyorum", "eşimden çok korkuyorum"). It is
 * matched on the prepared Latin input, which is already lower-cased and folded
 * by foldLatin (ı and İ to i, ş to s, ç to c, ğ to g, ö to o, ü to u), against
 * relation words folded by the same function, so Turkish letters and ASCII
 * typing both match. The relation word starts at a Unicode word boundary. Gem 3
 * accepts the false positives ("ondan korkuyorum" about an exam, "kocamdan
 * ayrılmaktan korkuyorum").
 */
export const TR_FEAR_RELATIONS: ReadonlyArray<string> = [
  'eşimden', 'kocamdan', 'karımdan', 'babamdan', 'annemden', 'abimden', 'ablamdan', 'ağabeyimden', 'sevgilimden',
  'nişanlımdan', 'kayınpederimden', 'kayınvalidemden', 'kaynanamdan', 'kayınbabamdan', 'amcamdan', 'dayımdan', 'ailemden', 'ondan',
]
// Architect ruling (21 Oct 2026): punctuation (commas, semicolons, colons,
// dashes and the rest of \p{P}) counts as a separator, like whitespace, so
// "eşimden, çok korkuyorum" is abuse; a word is a run of anything else. The
// three-word limit still applies. A missed abuse disclosure outweighs a false
// positive (Gem 3).
const TR_FEAR_PROXIMITY = new RegExp(`(?<![\\p{L}\\p{N}])(?:${TR_FEAR_RELATIONS.map((w) => foldLatin(w)).join('|')})[\\s\\p{P}]+(?:[^\\s\\p{P}]+[\\s\\p{P}]+){0,3}kork`, 'u')

/**
 * Gem 10 condition 2 (21 Oct 2026): the rule runs first on the RAW input,
 * lower-cased and folded by foldLatin only (case and Turkish letters; one
 * character in, one out, so no space is added or removed), where the
 * pattern's own [\s\p{P}] split is the tokeniser. Then on the prepared forms
 * (normaliseSeparators, stripped apostrophes, the letter-spacing collapse),
 * which can change the word count either way: an apostrophe split counts
 * "Ahmet'ten" as two words in the raw form and one in the prepared form, and
 * a run of two or more symbols becomes a space. A hit on any form is a hit,
 * so normalisation can add a match but never remove one.
 */
function trFearProximity(text: string, input: PreparedInput): boolean {
  const raw = foldLatin(text.toLowerCase())
  return TR_FEAR_PROXIMITY.test(raw) || input.latin.some((f) => TR_FEAR_PROXIMITY.test(f))
}

/**
 * WO#488 A2 (docs/wo488-architect.md): fear of a person is ABUSE in Persian and
 * Bengali, by the Turkish design: a relation word and the fear verb in one run
 * of text, with up to three words between them. Punctuation between them counts
 * as a separator, like whitespace (the Architect's comma ruling of 21 Oct 2026,
 * docs/wo482-architect.md), so "relation, fear" still fires.
 *
 * The relation lists: the WO's examples plus the drafts, all APPROVED by Gem 3
 * on 22 Oct 2026, with "father-in-law" added (docs/wo488-architect.md).
 *
 * Persian: "از" + relation + "میترسم". Matched on normaliseArabic output, so
 * Persian and Arabic keyboards (ی/ي, ک/ك) and ZWNJ ("می‌ترسم") all meet in one
 * form before matching (A4); "می ترسم" with a space also matches.
 */
export const FA_FEAR_RELATIONS: ReadonlyArray<string> = [
  'شوهرم', 'همسرم', 'پدرم', 'برادرم', 'زنم', 'مادرشوهرم',
  'خانوادم', // draft, approved: "my family" (FA_DISCLOSURE_MARKERS)
  '\u0645\u0627\u062F\u0631\u0645', // draft, approved: "my mother"
  'پدرشوهرم', // Gem 3, 22 Oct: "my father-in-law"
]
export const FA_FEAR_FROM = 'از'
export const FA_FEAR_VERB = 'میترسم'

// A word is letters, marks and digits: Persian and Bengali vowel signs are \p{M}.
const NOT_WORD = '(?<![\\p{L}\\p{M}\\p{N}])'
const WORD_ENDS = '(?![\\p{L}\\p{M}\\p{N}])'
const UP_TO_THREE_WORDS = '[\\s\\p{P}]+(?:[^\\s\\p{P}]+[\\s\\p{P}]+){0,3}'
const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

const FA_VERB_NORM = normaliseArabic(FA_FEAR_VERB)
const FA_FEAR_PROXIMITY = new RegExp(
  `${NOT_WORD}${escapeRe(normaliseArabic(FA_FEAR_FROM))}[\\s\\p{P}]+(?:${FA_FEAR_RELATIONS.map((w) => escapeRe(normaliseArabic(w))).join('|')})${WORD_ENDS}${UP_TO_THREE_WORDS}${escapeRe(FA_VERB_NORM.slice(0, 2))} ?${escapeRe(FA_VERB_NORM.slice(2))}`,
  'u',
)

/** On normaliseArabic of the raw input, then on the prepared Arabic form. */
function faFearProximity(text: string, input: PreparedInput): boolean {
  return FA_FEAR_PROXIMITY.test(normaliseArabic(text)) || FA_FEAR_PROXIMITY.test(input.arabic)
}

/**
 * Bengali: relation + "ভয়" + one of BN_FEAR_VERBS: the WO's "করে" and
 * "লাগে" ("কাছে যেতে ভয় করে" is the first with two words between), and the
 * first-person "করি" and "পাই" that Gem 3 added on 22 Oct. Negation follows
 * the verb in Bengali, so "... ভয় লাগে না" also fires; Gem 3 ruled that SAFE.
 * The relation word may carry a case ending (not separately ruled): -কে, -র, -ের, -য়ের, -এর, then an optional -ও. A closed list, so
 * "ভাইরাস" ("virus") is not "ভাই". Matched on the raw input lower-cased and NFC
 * (foldLatin), then on the prepared forms, as the Turkish rule.
 */
export const BN_FEAR_RELATIONS: ReadonlyArray<string> = [
  'স্বামী', 'শাশুড়ি', 'শাশুড়ী', 'শ্বশুর', 'বাবা', 'ভাই',
  'স্ত্রী', // draft, approved: "wife" (BN_DISCLOSURE_MARKERS)
  'পরিবার', // draft, approved: "family" (BN_DISCLOSURE_MARKERS)
]
export const BN_FEAR_NOUN = 'ভয়'
export const BN_FEAR_VERBS: ReadonlyArray<string> = ['করে', 'লাগে', 'করি', 'পাই']
const BN_CASE_ENDINGS = ['\u0995\u09C7', '\u09B0', '\u09C7\u09B0', '\u09AF\u09BC\u09C7\u09B0', '\u098F\u09B0']
const BN_ALSO = '\u0993'
const nfc = (s: string) => s.normalize('NFC')
const BN_FEAR_PROXIMITY = new RegExp(
  `${NOT_WORD}(?:${BN_FEAR_RELATIONS.map((w) => escapeRe(nfc(w))).join('|')})(?:${BN_CASE_ENDINGS.map(nfc).join('|')})?(?:${BN_ALSO})?${WORD_ENDS}${UP_TO_THREE_WORDS}${escapeRe(nfc(BN_FEAR_NOUN))}\\s+(?:${BN_FEAR_VERBS.map((v) => escapeRe(nfc(v))).join('|')})`,
  'u',
)

function bnFearProximity(text: string, input: PreparedInput): boolean {
  const raw = foldLatin(text.toLowerCase())
  return BN_FEAR_PROXIMITY.test(raw) || input.latin.some((f) => BN_FEAR_PROXIMITY.test(f))
}
